def min_cost_to_buy_shovels(n, m, k, costs, offers):
    # Create a list of shovels with their costs
    shovels = [(cost, i) for i, cost in enumerate(costs)]
    # Sort the shovels by cost
    shovels.sort()

    # Initialize a min heap to keep track of the cheapest shovels
    min_heap = []
    # Initialize a list to keep track of the number of shovels bought
    bought = [0] * n
    # Initialize a list to keep track of the number of shovels that can be bought for free
    free_shovels = [0] * n

    # Function to get the cheapest shovels for free
    def get_free_shovels():
        while min_heap and free_shovels[min_heap[0][1]] == 0:
            heappop(min_heap)
        if min_heap:
            return min_heap[0][0]
        return float('inf')

    # Function to buy shovels
    def buy_shovels():
        nonlocal min_heap, bought, free_shovels
        while min_heap and len(min_heap) > 0 and k > 0:
            cost, index = heappop(min_heap)
            if bought[index] == 0:
                bought[index] = 1
                k -= 1
            else:
                free_shovels[index] += 1
                k -= 1
            if k == 0:
                break
        if k > 0:
            return get_free_shovels()
        return float('inf')

    # Process each offer
    for offer in offers:
        x, y = offer
        for i in range(x - 1, -1, -1):
            if bought[i] == 0:
                heappush(min_heap, (costs[i], i))
                bought[i] = 1
                free_shovels[i] += 1
                if k == 0:
                    break
            else:
                free_shovels[i] += 1
                if k == 0:
                    break
        if k == 0:
            break

    # Calculate the minimum cost
    min_cost = 0
    for i in range(n):
        if bought[i] == 0:
            min_cost += costs[i]
        else:
            min_cost += buy_shovels()

    return min_cost

