def find_zero_sum_subset(n, a):
    # Create a dictionary to store the prefix sums and their indices
    prefix_sums = {}
    prefix_sum = 0
    for i, num in enumerate(a):
        prefix_sum += num
        if prefix_sum in prefix_sums:
            # If we find a prefix sum that is the negative of the current prefix sum
            # we can use the indices to form a subset with zero sum
            for j in prefix_sums[prefix_sum]:
                if j != i:
                    # Ensure the indices are unique
                    yield i, j
        else:
            prefix_sums[prefix_sum] = [i]
    # If no zero-sum subset is found, return an empty generator
