    # Create a list of indices for the positions in p
    positions = [i for i in range(len(a)) if i in p]

    # Check if the array can be sorted by swapping elements at the positions in p
    for i in range(len(positions) - 1):
        # Check if the element at the current position can be swapped with the next one
        if a[positions[i]] > a[positions[i] + 1]:
            # If the current element is greater than the next one, we need to swap them
            if a[positions[i]] > a[positions[i + 1]]:
                # Check if the next element is greater than the current one
                if a[positions[i + 1]] > a[positions[i]]:
                    # If the next element is greater, we can swap them
                    a[positions[i]], a[positions[i + 1]] = a[positions[i + 1]], a[positions[i]]
                    # Check if the array is sorted after the swap
                    if a == sorted(a):
                        return True
                    else:
                        # If not, we need to check the next possible swap
                        return False
                else:
